import React, { useMemo } from 'react';
import { isElement } from 'react-is';

import {
  _isSelectV2ContentElement,
  SelectV2ContentProps,
} from '../SelectContent.js';
import {
  _isSelectV2CustomTriggerElement,
  SelectV2CustomTriggerProps,
} from '../SelectCustomTrigger.js';
import { _isSelectV2DisplayValueElement } from '../SelectDisplayValue.js';
import { _isSelectV2EmptyState } from '../SelectEmptyState.js';
import { SelectV2FilterProps, _isFilter } from '../SelectFilter.js';
import {
  _isSelectV2PrefixElement,
  SelectV2PrefixProps,
} from '../SelectPrefix.js';
import {
  _isSelectV2TriggerElement,
  SelectV2TriggerProps,
} from '../SelectTrigger.js';

/** @internal */
interface _SelectV2Slots {
  Content: React.ReactElement<SelectV2ContentProps> | null;
  CustomTrigger: React.ReactElement<SelectV2CustomTriggerProps> | null;
  DisplayValue: React.ReactNode[] | null;
  Trigger: React.ReactElement<SelectV2TriggerProps> | null;
  Prefix: React.ReactElement<SelectV2PrefixProps> | null;
  Filter: React.ReactElement<SelectV2FilterProps> | null;
  EmptyState: React.ReactElement | null;
}

/**
 * Helper hook that will extract the Slots used in the select and collect the data / components.
 *
 * @internal
 */
export function useSelectV2Slots(children: React.ReactNode): _SelectV2Slots {
  return useMemo(() => {
    const slots: _SelectV2Slots = {
      Content: null,
      CustomTrigger: null,
      DisplayValue: null,
      Trigger: null,
      Prefix: null,
      Filter: null,
      EmptyState: null,
    };

    React.Children.forEach(children, (child) => {
      if (_isSelectV2ContentElement(child)) {
        slots.Content = child;
        // DISCUSS: Is this an issue when there are a lot of select options?
        React.Children.forEach(child.props.children, (child) => {
          if (_isFilter(child)) {
            slots.Filter = child;
            return;
          } else if (_isSelectV2EmptyState(child)) {
            slots.EmptyState = child;
          }
        });
        return;
      } else if (_isSelectV2TriggerElement(child)) {
        slots.Trigger = child;

        React.Children.forEach(child.props.children, (child) => {
          if (_isSelectV2DisplayValueElement(child)) {
            React.Children.forEach(child.props.children, (child) => {
              if (_isSelectV2PrefixElement(child)) {
                slots.Prefix = child;
                return;
              }

              // Concatenate free form content in the
              slots.DisplayValue = slots.DisplayValue || [];
              slots.DisplayValue.push(child);
            });
          }
        });
      } else if (_isSelectV2CustomTriggerElement(child)) {
        // The custom trigger should only use the first child.
        // TODO: What about fragments etc?
        const triggerValue = React.Children.toArray(child.props.children)[0];
        if (isElement(triggerValue)) {
          slots.CustomTrigger = triggerValue;
        }
      } else if (_isFilter(child)) {
        slots.Filter = child;
      }
    });

    return slots;
  }, [children]);
}
